{
  "justification": "Salience clusters around care-related services (NHS, social care), identity/sovereignty (EU, immigration), and economic fairness (economy, pay, poverty), implying strong pulls on Care, Loyalty, Equality and Proportionality. Authority and Sanctity are present but less dominant, seen in law-and-order, trust-in-politics, and environment/drug-use/morality concerns, and the direction of each is ambiguous because the instrument records issues, not positions.",
  "foundations": [
    {
      "foundation": "care",
      "basis": "NHS/Hospitals/Healthcare; Ageing population/Social care; Crime/Law and order/Violence/Vandalism (harm concerns); Pollution/Environment; Animal welfare; Drug abuse; Immigration (humanitarian framing)",
      "weight": 0.30
    },
    {
      "foundation": "loyalty",
      "basis": "Common Market/EU/Europe; Immigration; Defence/Foreign affairs/International terrorism; Scottish/Welsh Assembly/Devolution; Countryside/Rural life",
      "weight": 0.21
    },
    {
      "foundation": "authority",
      "basis": "Crime/Law and order/Violence/Vandalism; Lack of faith in govt/politics; Public services in general; Transport/Public transport; Scottish/Welsh Assembly/Devolution",
      "weight": 0.09
    },
    {
      "foundation": "sanctity",
      "basis": "Pollution/Environment; Morality/Individual behaviour/Lifestyle; Drug abuse; Animal welfare; NHS/Hospitals/Healthcare (purity-of-body framing)",
      "weight": 0.06
    },
    {
      "foundation": "equality",
      "basis": "Poverty/Inequality; Low pay/Minimum wage/Fair wages; Housing; Education/Schools; Race relations; Pensions/Social security",
      "weight": 0.18
    },
    {
      "foundation": "proportionality",
      "basis": "Economy/Economic situation; Unemployment/Factory closure/Lack of industry; Taxation; Inflation/Prices; Privatisation; Nationalisation; Trade unions/Strikes",
      "weight": 0.16
    }
  ]
}
